import json,re,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
posts=[]
def table(caption,heads,rows):
 return '<div class="article-table-scroll"><table><caption>'+caption+'</caption><thead><tr>'+''.join('<th scope="col">'+str(v)+'</th>'for v in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'if i==0 else '<td>')+str(v)+('</th>'if i==0 else '</td>')for i,v in enumerate(row))+'</tr>'for row in rows)+'</tbody></table></div>'
def add(slug,title,seo,desc,opening,sections,heads,rows,sources,alt,faqs):
 body='<p><strong>'+opening+'</strong></p><p>Every amount in the worked case is an original fictional USD planning assumption. It is not an industry benchmark, a customer result or a prediction.</p>'
 links=[]
 for ident,heading,content in sections:body+='<h2 id="'+ident+'">'+heading+'</h2>'+content;links.append([ident,heading])
 body+='<h2 id="worksheet">Use the worksheet with your own records</h2><p><a href="/downloads/'+slug+'-worksheet.html" download>Download the printable, editable HTML worksheet</a>. It contains the completed example and a blank table. Open it in a browser, edit the blank fields, calculate the outputs using the stated method and print to PDF or paper. It does not automatically calculate results or replace your accounting records.</p>'
 body+='<h2 id="sources">Method references and source notes</h2><p>The method references below support the definitions. The examples, assumptions and decision checks on this page are independently constructed.</p><ul>'+''.join('<li><a href="'+url+'">'+label+'</a></li>'for label,url in sources)+'</ul>'
 p=dict(slug=slug,title=title,seoTitle=seo,description=desc,metaDescription=desc,opening=opening,tag='Break-Even Concepts',tags=['Business finance','Worked example','Decision worksheet'],published='2026-11-03',modified='2026-11-03',editorialStatus='draft',image='/images/title-covers/day1-'+slug+'-20261103.webp',alt=alt,imageCaption='Topic illustration. All financial examples in the article are fictional.',html=body,sectionLinks=links+[['worksheet','Worksheet'],['sources','Sources']],faq=[dict(q=q,a=a)for q,a in faqs])
 posts.append(p)
 worksheet='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+' worksheet</title><style>body{font:17px/1.6 system-ui;max-width:1000px;margin:36px auto;padding:20px;color:#142e3e}h1,h2{color:#075b61}table{width:100%;border-collapse:collapse;font-size:15px}th,td{border:1px solid #b8ced0;padding:10px;text-align:left}thead{background:#e8f5f2}[contenteditable]{background:#fff8dc;min-width:80px}caption{text-align:left;font-weight:bold;padding:12px 0}.article-table-scroll{overflow:auto}@media print{body{font-size:12px;margin:0}button{display:none}}</style><h1>'+html.escape(title)+'</h1><p>MyBreakEven | Original fictional USD example | 3 November 2026</p><p>Edit the highlighted blank table in your browser. This worksheet does not calculate automatically. Print your completed copy; save the original separately. Browser editing is temporary until printed/saved.</p>'+table('Completed reference',heads,rows)+'<h2>Your case</h2><p contenteditable="true">Business / period / source records / assumptions / reviewer / decision / review date</p>'+table('Blank worksheet',heads,[[row[0]]+['<span contenteditable="true">Enter here</span>'for _ in heads[1:]]for row in rows])+'<h2>Method and controls</h2>'+''.join('<h3>'+heading+'</h3>'+re.sub(r'<a [^>]*>(.*?)</a>',r'\1',content)for _,heading,content in sections[:2])+'<p><a href="https://mybreakeven.com/blogs/'+slug+'/">Full method and limitations</a></p></html>'
 dest=ROOT/'public/downloads'/f'{slug}-worksheet.html';dest.write_text(worksheet)

add('customer-profitability-analysis','Customer Profitability Analysis: Revenue, Cost to Serve and Decisions','Customer Profitability Analysis: Formula & Example','Measure customer profit with a reconciled cost-to-serve example. Separate avoidable costs, shared overhead and cash collection before changing an account.',
'Customer profitability analysis compares a customer’s net revenue with the direct and shared costs of serving that customer during the same period. Show contribution and allocated profit separately before deciding whether a relationship should change.',[
('formula','Define the period and the cost boundary','<p>Start with a customer-month, quarter or year. Use earned revenue after discounts, credits and returns for that period. Keep collections in a separate dated view: an unpaid invoice can create accounting revenue without available cash. Define whether your result includes acquisition spending, account support, general overhead and owner work.</p><p><strong>Customer contribution = net revenue − directly traceable delivery and service costs.</strong> Then subtract assigned shared service costs to obtain the specifically defined allocated result. Label the boundary; do not call a partially costed margin company net income. A customer’s lifetime value uses a different horizon and needs retention assumptions.</p>'),
('example','Reconcile three customers to the business total',table('Fictional monthly customer ledger',['Measure','Customer A','Customer B','Customer C','Total'],[['Net revenue','$6,000','$4,000','$2,000','$12,000'],['Direct delivery','$2,400','$2,000','$1,200','$5,600'],['Support hours','10','20','30','60'],['Support at $40/hour','$400','$800','$1,200','$2,400'],['Contribution after support','$3,200','$1,200','−$400','$4,000'],['General overhead allocated','$900','$600','$300','$1,800'],['Allocated result','$2,300','$600','−$700','$2,200']])+'<p>The support pool is $2,400 divided by 60 practical support hours, giving $40 per hour. General overhead is allocated by revenue only to reconcile the remaining $1,800. Its allocation is a reporting choice, not evidence that the cash disappears when a customer leaves. Total revenue of $12,000 less $5,600 delivery, $2,400 support and $1,800 overhead equals $2,200.</p>'),
('drivers','Choose drivers that explain actual work','<p>Use order lines for processing, support time for assistance, shipments for dispatch and documented collection effort for chasing overdue balances. Do not allocate every pool by sales simply because sales is available. Record the pool amount, source ledger, included activity, denominator and each customer’s usage. The sum of allocations must equal the amount assigned; idle capacity or unassigned overhead should remain visible.</p><p>For acquisition cost, choose and disclose a treatment. Expensing all campaign spend in the acquisition month may be useful for that month’s result; spreading it over an assumed relationship produces a different managerial measure. Neither choice should silently mix lifetime acquisition cost with one month’s revenue.</p>'),
('decision','Test an action instead of automatically dropping the customer','<p>Customer C looks loss-making after allocation. Suppose a standard-order policy removes ten support hours. At the chosen $40 rate, the ledger shows $400 less assigned support and a zero contribution after support. But if salaried staff are still paid, near-term cash does not improve by $400. Instead, released hours may let the same team serve better work.</p><p>Before repricing or exiting, list contract commitments, collection risk, rework, spare capacity and costs genuinely avoided. Compare a scoped service level, paid rush requests, minimum order or staged price change with the current account. A negative allocated result is a reason to investigate, not an automatic customer termination rule.</p>'),
('workflow','Build a monthly account review that can be audited','<ol><li>Reconcile customer net revenue to the sales ledger.</li><li>Trace delivery, refunds and customer-specific effort from source records.</li><li>Allocate only identified service pools using documented drivers.</li><li>Show unassigned overhead and reconcile the complete business result.</li><li>Choose an action, name an owner and review the next period’s actuals.</li></ol><p>Use the <a href="/blogs/agency-client-profitability/">agency client profitability guide</a> for a service-account application, and the <a href="/calculators/cleaning-contract-profit-calculator/">cleaning contract profit calculator</a> for a contract-specific cost boundary. Check those records against the broader <a href="/blogs/contribution-margin-income-statement/">contribution income statement</a>.</p>')],
['Measure','Customer A','Customer B','Customer C','Total'],[['Net revenue',6000,4000,2000,12000],['Direct delivery',2400,2000,1200,5600],['Support hours',10,20,30,60],['Assigned support',400,800,1200,2400],['Contribution after support',3200,1200,-400,4000],['General overhead',900,600,300,1800],['Allocated result',2300,600,-700,2200]],
[('BDC: customer profitability and cost to serve','https://www.bdc.ca/en/articles-tools/marketing-sales-export/sales/5-step-customer-profitability-analysis')],
'Business owner comparing three customer folders with delivery, support and invoice records.',[('Is a high-revenue customer always profitable?','No. Discounts, delivery effort, exceptions, support and collection work can consume the apparent margin. Compare consistently costed results for the same period.'),('Should shared overhead determine whether to drop a customer?','Not by itself. Test avoidable costs and released capacity; allocated overhead may remain after the account leaves.')])

add('roas-vs-roi','ROAS vs ROI: Follow One Campaign from Revenue to Profit','ROAS vs ROI: Formulas, Costs & Worked Example','Compare ROAS and ROI using the same campaign ledger. Account for refunds, delivery costs and creative fees, and state exactly which investment denominator you use.',
'ROAS divides attributed conversion revenue by ad spend. ROI compares a defined net profit with a defined investment cost. A high ROAS can coexist with a loss when product, fulfillment, refunds and campaign costs absorb the revenue.',[
('formula','Write both formulas and state what each includes','<p><strong>ROAS = attributed conversion revenue ÷ advertising spend.</strong> A 4× result means $4 attributed revenue for each $1 of media spend; it is not $4 profit. Where a platform tracks non-revenue conversion value, call the metric conversion-value ROAS rather than cash sales.</p><p><strong>ROI = net return ÷ defined investment cost × 100%.</strong> Net return subtracts the costs included in that definition. Some teams report campaign profit divided by media/marketing investment; others divide by all included costs. Both can be interpretable, but only if the numerator and denominator are explicit and comparable.</p>'),
('ledger','Work through one completed campaign',table('Original fictional campaign, one matched reporting window',['Ledger item','Amount','Treatment'],[['Net attributed revenue','$12,000','After credits/returns in this example'],['Ad spend','$3,000','Media only'],['Product costs','$5,400','Cost of fulfilled sales'],['Fulfillment and transaction fees','$1,800','Additional sale-linked costs'],['Creative and campaign support','$1,200','Separate from media'],['Included total cost','$11,400','Sum of all four cost lines'],['Profit after included costs','$600','$12,000 − $11,400']])+'<p>ROAS is $12,000 ÷ $3,000 = <strong>4×, or 400%</strong>. Total-cost ROI is $600 ÷ $11,400 = <strong>5.26%</strong>. A separately labelled marketing-investment return is $600 ÷ ($3,000 + $1,200) = <strong>14.29%</strong>. The different percentages do not conflict: their cost bases differ. The case excludes general company overhead, interest and tax, so $600 is not represented as company net income.</p>'),
('threshold','Find the threshold implied by this exact ledger','<p>Product and fulfillment costs total $7,200, or 60% of net revenue. The pre-marketing contribution ratio is 40%. Ignoring the separate creative/support cost, media-only break-even ROAS is 1 ÷ 0.40 = 2.5×. Including $1,200 creative/support and holding $3,000 media spend fixed requires revenue of ($3,000 + $1,200) ÷ 0.40 = $10,500, or <strong>3.5× media ROAS</strong>.</p><p>This threshold assumes a stable cost ratio, net revenue definition and campaign support budget. If returns, order mix or fulfillment rates change, recalculate. Use the existing <a href="/calculators/break-even-roas-calculator/">break-even ROAS calculator</a> and its <a href="/blogs/break-even-roas-formula/">formula explanation</a> for the threshold task rather than creating a second ROAS tool.</p>'),
('sensitivity','Keep the sales result constant and change the economics','<p>If fulfillment and fees increase by $900, profit falls from $600 to <strong>−$300</strong> while ROAS remains 4×. Included costs become $12,300 and total-cost ROI becomes −2.44%. That is why creative changes that raise revenue can still damage profit when they also increase discounts, returns or expensive deliveries.</p><p>Track net revenue, contribution before media, campaign profit and cash settlement together. Compare cohorts only after a consistent conversion/return window. An order reported today may be returned later, and a payment processor can settle cash on another date.</p>'),
('attribution','Do not turn attribution into proof of incremental sales','<p>Attributed conversions follow a platform’s measurement model. They do not establish how many sales would have happened without advertising. Separate branded/returning-customer attribution from a documented incrementality test. Do not combine overlapping platform revenue totals as though every order were unique.</p><p>Before increasing spend, verify currency, revenue events, refunds, attribution windows, cost imports and the investment definition. Review <a href="/blogs/how-to-price-products-for-ecommerce/">ecommerce unit economics</a> and the <a href="/calculators/business-roi-calculator/">business ROI calculator</a> when the decision includes more than advertising.</p>')],
['Measure','USD / result'],[['Net attributed revenue',12000],['Media spend',3000],['Product cost',5400],['Fulfillment and fees',1800],['Creative/support',1200],['Included profit',600],['ROAS multiple',4],['Total cost ROI percent','5.2631579'],['Marketing investment return percent','14.2857143']],
[('Google Ads: return on investment and cost boundaries','https://support.google.com/google-ads/answer/14090?hl=en'),('Google Ads: attributed ROAS versus incremental ROAS','https://support.google.com/google-ads/answer/14102450?hl=en')],
'Marketer comparing attributed advertising revenue with a separate product-cost and campaign-profit ledger.',[('Is 400% ROAS the same as 400% ROI?','No. A 400% ROAS is 4× attributed value divided by media spend. ROI uses net return and a separately defined investment denominator.'),('Which result should I use for scaling?','Review contribution and campaign profit, attribution quality, capacity and cash timing together. A revenue ratio alone does not establish profitable incremental growth.')])

add('sales-forecast-small-business','Sales Forecast Formula: Build a Capacity-Checked Small-Business Plan','Sales Forecast Formula & Small-Business Template','Build a bottom-up sales forecast from units, price and customer evidence. Check capacity, separate bookings from revenue and compare scenarios with a printable template.',
'A practical sales forecast sums expected units multiplied by net selling price for each offer and period. Build the unit assumptions from customer evidence, check delivery capacity, and keep revenue recognition and collection dates separate.',[
('method','Choose a method that matches the evidence you have','<p>For repeat services, begin with opening customers, expected completed work and known renewals. For a product line, use expected sold units and net unit prices. For a qualified pipeline, sum opportunity value multiplied by a documented close probability for the relevant period. Historical growth can supply a baseline, but unexplained percentage growth is not customer evidence.</p><p><strong>Forecast sales = Σ(expected units × net unit price).</strong> A weighted pipeline is an expectation across uncertain outcomes, not a promise that a fractional contract will close. Do not add the same sale again when it appears in both a customer schedule and the pipeline.</p>'),
('example','Build a two-offer month before applying a growth rate',table('Fictional planning month',['Offer','Completed jobs','Net price','Revenue','Hours/job','Worker-hours'],[['Recurring service','40','$180','$7,200','2','80'],['One-off service','12','$300','$3,600','4','48'],['Total','52','Mixed','$10,800','Mixed','128']])+'<p>The team has 160 scheduled worker-hours, of which 80% are realistically productive: <strong>128 hours</strong>. The base case uses every productive hour. A target of 60 recurring jobs and 12 one-off jobs would need 168 hours, so demand or sales ambition alone cannot support it. Keep worker-hours distinct from elapsed clock hours when several people attend a job.</p>'),
('scenario','Use scenarios that change the actual drivers',table('Demand scenarios with the same illustrative prices',['Scenario','Recurring jobs','One-off jobs','Revenue','Hours needed','Capacity status'],[['Downside','32','8','$8,160','96','32 hours available'],['Base','40','12','$10,800','128','At capacity'],['Demand upside','48','16','$13,440','160','32 hours beyond capacity']])+'<p>The upside is a demand case, not an executable delivery forecast. It needs 32 more productive hours, a revised offer mix or rescheduling. If overtime or contractors add cost, update contribution and cash along with sales. If cancellations are already incorporated in completed-job assumptions, do not subtract them a second time.</p>'),
('cash','Separate signed work, delivered revenue and cash received','<p>A signed $3,000 agreement in November might be delivered in December and collected in January. Keep separate columns for signed bookings, the revenue period under the applicable accounting treatment, and the expected receipt date. The illustrative tables use completed service work as the sales basis; they are not tax-method guidance.</p><p>Once sales are built, send dated receipts into the <a href="/calculators/cash-flow-forecast-template/">cash-flow forecast</a>. Use the <a href="/blogs/rolling-forecast/">rolling forecast guide</a> to update the horizon as actual months close. These are linked tasks, not interchangeable templates.</p>'),
('review','Measure forecast error and improve the assumptions','<p>Freeze a dated forecast version before the month begins. Compare actual units, net price, mix, cancellations and timing against that version. If actual revenue is $10,200 against $10,800, the dollar error is −$600 and the shortfall versus forecast is 5.56%. This stated denominator is forecast revenue; a metric using actual revenue would produce a different percentage.</p><p>Review persistent bias rather than rewriting the old forecast to match actuals. For a new business, replace weak assumptions with paid pilots, signed scope, customer interviews and observed conversion rates as evidence accumulates. Retain the source date and owner of each assumption in the <a href="/resources/business-plan-template/">business plan evidence register</a>.</p>')],
['Scenario','Recurring jobs','One-off jobs','Net revenue','Worker-hours'],[['Downside',32,8,8160,96],['Base',40,12,10800,128],['Demand upside',48,16,13440,160]],
[('Salesforce: forecasting methods and review process','https://www.salesforce.com/sales/analytics/sales-forecasting-guide/')],
'Business owner building a sales plan from order cards, a calendar and a qualified pipeline beside product samples.',[('Can a sales target be used as a forecast?','A target states an ambition. A forecast estimates an outcome from stated evidence and assumptions. Keep both visible rather than treating the target as proof.'),('Does the forecast show cash available?','Not by itself. Put delivery, invoice and collection dates into a separate dated cash schedule.')])

add('cost-volume-profit-analysis','Cost Volume Profit Analysis: Break-Even, Target Profit and Capacity','Cost Volume Profit Analysis: Formula & Scenarios','Use CVP analysis to test price, costs, volume, sales mix and capacity. Follow reconciled examples showing why a profitable target can fail after a step in fixed costs.',
'Cost-volume-profit analysis tests how price, variable costs, fixed costs and sold volume combine to produce operating profit. Break-even is its zero-profit case; the useful business decision also checks demand, product mix and the capacity range.',[
('formula','Start with one consistent unit and cost boundary','<p><strong>Operating profit = units × (net price − variable cost per unit) − fixed operating costs.</strong> Contribution per unit is net price less variable cost. The contribution ratio divides that contribution by price. Break-even units equal fixed costs divided by positive unit contribution. Required units for a profit target equal (fixed costs + target operating profit) divided by unit contribution.</p><p>If contribution is zero or negative, selling more of the unchanged offer does not cover positive fixed costs. Keep every amount in the same period and currency. Owner wages included in fixed costs must not be added again as a separate profit goal. Drawings and financing require separate cash treatment.</p>'),
('case','Reconcile the profit at several volumes',table('Original fictional monthly case: $120 price, $72 variable cost, $9,600 fixed costs',['Sold units','Sales','Variable cost','Contribution','Operating profit'],[['150','$18,000','$10,800','$7,200','−$2,400'],['200','$24,000','$14,400','$9,600','$0'],['250','$30,000','$18,000','$12,000','$2,400'],['300','$36,000','$21,600','$14,400','$4,800']])+'<p>Unit contribution is $48, the contribution ratio is 40%, and exact break-even is 200 units or $24,000. A $4,800 operating-profit target requires 300 units. A $5,000 target would require 304.1667 units mathematically; 305 whole units produce $5,040 profit under the unchanged assumptions.</p>'),
('range','Check the capacity step before trusting the target','<p>Suppose existing resources can deliver only 260 units. Selling 300 requires another $2,400 monthly capacity commitment. The fixed-cost base becomes $12,000 and 300 units now produce $2,400, not $4,800. To recover the original $4,800 target at the same price and variable rate requires <strong>350 units</strong>. That second target also needs its own capacity and demand check.</p><p>A discounted price of $110 leaves only $38 contribution at the original $72 variable rate. With the original $9,600 fixed base, break-even becomes 252.6316 exact units, or 253 whole units. These comparisons isolate a changed assumption; combining them without rebuilding the full model would misstate the answer.</p>'),
('mix','A sales mix changes what an average unit means','<p>For two offers contributing $40 and $70 per unit, a 3:2 unit mix creates a five-unit bundle with $260 contribution. At $10,400 fixed cost, break-even is 40 bundles: 120 units of the first offer and 80 of the second. The weighted unit contribution is $52. If the mix changes, that average no longer applies.</p><p>Use the existing <a href="/blogs/break-even-multiple-products-sales-mix/">multiple-product break-even guide</a> for the mix calculation. The <a href="/blogs/contribution-margin-income-statement/">contribution income statement</a> reconciles cost behavior; the <a href="/blogs/target-profit-sales-formula/">target-profit guide</a> owns the detailed units-and-sales task.</p>'),
('checks','Know when the straight-line model stops answering the question','<p>Simple CVP assumes stable price and variable cost per unit, a relevant fixed-cost range, meaningful cost classification and a stated mix. Inventory changes, capacity tiers, waste, payment fees and channel commissions can require a more detailed model. Profit is not available cash: collection delays, inventory purchases, debt principal and capital expenditure must also be scheduled.</p><p>Use <a href="/blogs/flexible-budget-variance-analysis/">flexible budget variance analysis</a> to compare actual performance at actual volume rather than blaming a revenue shortfall on cost control. Treat a feasible profit target as a plan to test, not proof that buyers will order it.</p>')],
['Units','Sales','Variable costs','Contribution','Operating profit'],[[150,18000,10800,7200,-2400],[200,24000,14400,9600,0],[250,30000,18000,12000,2400],[300,36000,21600,14400,4800]],
[('ACCA: CVP calculations, graphs and assumptions','https://www.accaglobal.com/gb/en/student/exam-support-resources/fundamentals-exams-study-resources/f5/technical-articles/CVP-analysis.html'),('FAO: CVP and decision making','https://www.fao.org/4/w4343e/w4343e06.htm')],
'Product-business manager reviewing price, variable materials and fixed overhead beside a packaging workbench.',[('Is CVP the same as break-even analysis?','Break-even is the zero-profit case within CVP. CVP also compares target profits and changes in volume, price, costs and mix.'),('Why can a correct target still fail?','It may exceed capacity, rely on unsupported demand or cross a fixed-cost step. A profit model also does not establish cash availability.')])

add('cost-per-hire-vs-employee-cost','Cost per Hire vs Employee Cost: Two Different Budgets','Cost per Hire vs Employee Cost: Formula & Example','Calculate recruiting cost per completed hire, then build a separate first-year employment budget. Include internal time consistently without double-counting onboarding.',
'Cost per hire divides the recruiting costs included in a defined period by completed hires in that period. Employee cost measures the ongoing cost of employing someone. The two budgets answer different questions and should not be added without checking shared items.',[
('formula','Define the recruiting numerator and the hires denominator','<p><strong>Cost per hire = (included external recruiting costs + included internal recruiting costs) ÷ completed hires.</strong> External costs may include job ads, agency fees and screening. Internal costs may include recruiting staff and documented interviewer time. Use one written cost policy so months and roles can be compared.</p><p>Count actual hires using a consistent event, such as accepted offers or starts, and disclose which event you use. An open vacancy is not a hire. When a period has costs but zero hires, the ratio is undefined; report the spend and zero denominator rather than returning $0 cost per hire. Multi-month campaigns need a reconciliation so costs and outcomes are not silently moved between periods.</p>'),
('example','Calculate a completed two-hire campaign',table('Original fictional recruiting period',['Item','Calculation','Cost'],[['Job advertising','Campaign invoices','$1,200'],['Agency/screening','Separate invoice records','$1,800'],['Recruiter effort','30 hours × $40','$1,200'],['Manager interviews','20 hours × $60','$1,200'],['Total recruiting cost','External $3,000 + internal $2,400','$5,400'],['Completed hires','Two starts','2'],['Cost per hire','$5,400 ÷ 2','$2,700']])+'<p>The hourly values are planning assumptions, not current pay benchmarks. If interviewer salary is already in the internal recruiting pool, do not add the same hours again. A cash-only view might show $3,000 external spend, but it omits $2,400 of valued staff effort; label the two views rather than comparing them as identical metrics.</p>'),
('first-year','Build the employment budget separately','<p>For one illustrative role, assume $48,000 salary, $4,800 employer charges, $3,600 benefits, $1,200 equipment/software and $1,000 onboarding paid time outside the recruiting definition. The first-year employment budget before recruitment is <strong>$58,600</strong>. Adding the separately assigned $2,700 recruitment cost gives <strong>$61,300</strong>.</p><p>These are chosen amounts, not a payroll tax or benefit rate. A hiring bonus, relocation payment, training time or recruiter salary must appear only once under the adopted boundary. Recurring-year cost can differ from first-year cost because recruiting and equipment are not necessarily repeated.</p>'),
('capacity','Distinguish hiring efficiency from hiring quality','<p>A lower cost per hire does not prove a better hire. Compare like roles and channels, then review acceptance, start dates, retention and observed job performance. A cheap process with repeated replacement hires can cost more overall. Small samples also move sharply: one additional start changes a two-hire denominator by 50%.</p><p>Time to fill, recruiting conversion yield and cost per productive hour answer other questions. A team may hire quickly but lack work, onboarding capacity or cash to support the position. Use the <a href="/calculators/employee-cost-calculator/">employee cost calculator</a> for recurring and productive-hour economics, and the <a href="/calculators/cash-flow-forecast-template/">dated cash forecast</a> for the payroll funding period.</p>'),
('controls','Keep a recruiting ledger that can be reproduced','<ol><li>Choose the reporting period and the counted hire event.</li><li>List invoices and internal hours with an owner and source reference.</li><li>Document shared-cost allocation and any excluded costs.</li><li>Reconcile hires, costs, open campaigns and timing differences.</li><li>Compare channels only after matching cost and role definitions.</li></ol><p>Keep applicant records secure and use job-related review criteria. The financial worksheet does not determine employment-law obligations, eligibility or candidate suitability.</p>')],
['Item','Quantity / rate','USD cost'],[['External advertising','Invoices',1200],['Agency/screening','Invoices',1800],['Recruiter effort','30 × 40',1200],['Manager interviews','20 × 60',1200],['Total recruitment','Sum',5400],['Completed hires','Starts',2],['Cost per hire','5400 / 2',2700],['First year before recruitment','Illustrative role',58600],['First year including recruitment','58600 + 2700',61300]],
[('SHRM: Essentials of HR Management excerpt, cost-per-hire components','https://learnhrm.shrm.org/wp-content/uploads/2015/12/EHRM_demo_excerpt.pdf')],
'HR manager reviewing interview folders, recruiting invoices and a hiring calendar in a professional small-business office.',[('Does cost per hire include annual salary?','The employee’s ongoing annual salary belongs in the employment budget, not automatically in recruiting cost. Recruiting staff effort can be part of internal recruiting costs.'),('What if no one was hired?','Report recruiting spend and zero completed hires. Division by zero does not produce a meaningful cost-per-hire result.')])

add('business-financial-contingency-plan','Financial Contingency Plan: Cash Triggers, Actions and Funding','Financial Contingency Plan: Cash Triggers & Template','Build a financial contingency plan with dated cash scenarios, trigger levels, owners and verified funding. Use a reconciled example instead of an arbitrary reserve percentage.',
'A financial contingency plan defines what the business will do when cash assumptions fail: the trigger, decision owner, dated response and funding actually available. It complements the cash forecast and operational continuity plan; it is not a promise that emergency finance will be approved.',[
('structure','Connect a risk to a date and an accountable action','<p>Choose a planning horizon that captures your payment commitments. List opening usable cash, expected receipts and committed payments by week or date. Separate restricted balances, unapproved borrowing and expected insurance recoveries from cash available to pay bills. Identify which receipts depend on customer acceptance, processing delays or unresolved disputes.</p><p>For each risk, record the event, a measurable trigger, the owner, the response deadline, the action’s cash effect and the dependency that could prevent it. A reserve target should follow the business’s downside timing and tolerance, not an unexplained percentage copied from another company.</p>'),
('case','Model the shortage before assuming a funding solution',table('Original fictional four-week cash case, before corrective action',['Case','Opening usable cash','Receipts','Payments','Closing cash'],[['Base','$18,000','$8,000','$20,000','$6,000'],['Customer delay','$18,000','$2,000','$20,000','$0'],['Delay plus repair','$18,000','$2,000','$22,500','−$2,500']])+'<p>Use a chosen $5,000 minimum cash floor for this case. The base case stays $1,000 above it. The customer-delay case needs $5,000 of timely improvement to restore the floor, and the combined downside needs $7,500. These are aggregate four-week checks; a payroll payment before the week-four receipt may create an earlier, larger need. The dated worksheet must test that ordering.</p>'),
('actions','Build a response that can actually occur before the bill',table('Illustrative response to the combined downside',['Action','Cash improvement','Evidence needed'],[['Move discretionary equipment purchase','$2,000','Purchase not committed; no penalty'],['Reschedule a supplier payment by agreement','$1,500','Written acceptance and new due date'],['Available credit draw','$4,000','Existing facility, conditions met, timely draw'],['Total improvement','$7,500','Do not count unconfirmed actions'],['Revised closing cash','$5,000','−$2,500 + $7,500']])+'<p>Deferring a payment shifts the obligation into a later period; it does not eliminate the cost. Add the new payment date and debt service to later weeks. Avoid showing credit as ordinary revenue. If the lender can suspend the line or the business fails its conditions, the draw must not appear as dependable cash.</p>'),
('trigger','Write an escalation ladder with a decision owner','<p>An illustrative green level is forecast cash at or above the chosen floor, with a weekly review. Amber begins when a dated forecast falls below that floor or a material receipt slips: the finance owner confirms collection status and pauses uncommitted discretionary spending. Red is an inability to meet a critical due payment: the owner escalates immediately, verifies financing and contacts the affected counterparties before making unsupported promises.</p><p>The numbers and color levels belong to this fictional case. In a real plan, set them around payroll, critical suppliers, legal commitments, funding terms and operational resilience. Do not advise missing tax or wage obligations as a routine liquidity tactic.</p>'),
('test','Rehearse the plan and reconcile it after each review','<p>Test a delayed receipt, a lost customer, an equipment failure and a funding source that is unavailable at the same time. Keep source evidence for cash, counterparties, approvals and facility conditions. Check after the event whether the action occurred on time and whether a temporary fix created another shortage.</p><p>Use the <a href="/calculators/cash-flow-forecast-template/">13-week cash forecast</a> for dated payments, the <a href="/blogs/cash-flow-problems/">cash-flow recovery guide</a> for causes and responses, and your <a href="/resources/business-plan-template/">business plan</a> for the assumptions and owners. The broader business continuity task also covers staffing, systems, premises and recovery priorities; this article owns the financial response.</p>')],
['Scenario / action','Opening cash','Receipts / improvement','Payments','Closing cash'],[['Base',18000,8000,20000,6000],['Customer delay',18000,2000,20000,0],['Delay plus repair',18000,2000,22500,-2500],['Actions combined',-2500,7500,0,5000]],
[('SBA: business management resources, including emergency preparedness','https://www.sba.gov/business-guide/manage-your-business')],
'Business owner examining a cash-payment calendar, downside scenario and confirmed backup funding folder.',[('How large should the emergency reserve be?','Base it on dated downside cash needs, commitments, available financing and risk tolerance. The illustrative $5,000 floor is not a universal recommendation.'),('Can expected insurance or a new loan be counted as available cash?','Only with a supportable amount and timing, and after relevant conditions are met. Pending approval is not immediately available cash.')])

add('accounts-receivable-vs-accounts-payable','Accounts Receivable vs Accounts Payable: One Invoice, Two Ledgers','Accounts Receivable vs Payable: Entries & Cash Dates','Compare receivables and payables with matched seller and buyer entries. Reconcile an invoice, credit and partial payment without confusing revenue, expense and cash.',
'Accounts receivable is an amount customers owe your business; accounts payable is an amount your business owes suppliers. The same credit transaction can create the seller’s receivable and the buyer’s payable, but each business keeps its own ledger and payment dates.',[
('comparison','Compare the direction, classification and supporting records',table('Ordinary trade-account comparison; the accounting framework still applies',['Question','Accounts receivable','Accounts payable'],[['Who owes whom?','Customer owes the business','Business owes supplier'],['Usual balance-sheet category','Asset','Liability'],['Main evidence','Sales invoice, credit, receipt','Supplier bill, credit, payment'],['Normal increase entry','Debit AR','Credit AP'],['Cash event when settled','Business receives cash','Business pays cash']])+'<p>Trade balances are often current, but classification depends on the operating cycle and terms. A debit or credit is an accounting direction, not a synonym for good or bad. Customer deposits and prepayments can require other accounts; do not force every balance into ordinary AR or AP.</p>'),
('example','Follow an invoice, credit and partial payment','<p>In a fictional accrual-basis example with no tax, Harbor Supplies delivers $3,000 of materials to a customer on November 5, with payment due December 5. The customer receives and records the materials as inventory. On November 12, a valid $300 return is accepted. On November 25, the customer pays $1,000. The remaining open balance is <strong>$1,700</strong>.</p>'+table('Matched entries; seller inventory/COGS entries are outside this comparison',['Event','Seller ledger','Buyer ledger'],[['Invoice / delivery','Debit AR $3,000; credit revenue $3,000','Debit inventory $3,000; credit AP $3,000'],['Accepted return','Debit sales returns $300; credit AR $300','Debit AP $300; credit inventory $300'],['Partial payment','Debit cash $1,000; credit AR $1,000','Debit AP $1,000; credit cash $1,000'],['Open amount','$3,000 − $300 − $1,000 = $1,700','$3,000 − $300 − $1,000 = $1,700']])+'<p>The seller’s inventory cost and related cost-of-sales reversal are excluded from this narrowly matched ledger example because the acquisition cost was not given. A complete accounting record must include them where applicable. Sales tax, foreign currency, discounts, impairment and framework-specific recognition require additional treatment.</p>'),
('timing','The payment changes cash without creating the same revenue twice','<p>The seller’s invoiced net sales in this case are $2,700 after the return, but the cash collected so far is $1,000. The receipt reduces AR; it is not another $1,000 of accrual revenue. The buyer’s payment reduces AP; it does not automatically create another expense. Buying inventory is also different from recognizing cost of goods sold when that inventory is sold.</p><p>The outstanding $1,700 affects collection or payment planning. Put its expected settlement date into the <a href="/calculators/cash-flow-forecast-template/">cash forecast</a>. The balance alone does not say whether it is overdue; compare it with the agreed due date and any dispute or amendment.</p>'),
('controls','Reconcile the open balances instead of relying only on totals','<p>For AR, opening balance plus invoices less credits, receipts and applicable write-offs should explain the closing ledger. For AP, opening balance plus accepted bills less credits and payments should explain the closing ledger. Reconcile customer/supplier subledgers with the control account, then match settlement amounts to the bank.</p><p>Review unapplied receipts, duplicate bills, unmatched credits and cut-off errors. Keep disputed amounts visible. Amounts due from and to the same counterparty should not be netted casually: applicable offsetting rules and agreements matter. Use aging buckets based on a consistently stated method, such as days past due.</p>'),
('next','Choose the detailed workflow after understanding the difference','<p>AR management concerns invoicing, collection, disputes and customer credit exposure. AP management concerns approved bills, valid suppliers, due dates and controlled disbursement. This comparison does not replace either full process. For the collection-speed calculation, use <a href="/blogs/how-to-calculate-days-sales-outstanding/">DSO</a>; for the broader balance relationship, use <a href="/blogs/how-to-calculate-working-capital/">working capital</a>. Keep the <a href="/blogs/cash-flow-statement/">historical cash-flow statement</a> separate from the forecast of future dates.</p>')],
['Event','Seller AR balance','Buyer AP balance','Cash transferred'],[['Opening',0,0,0],['Invoice',3000,3000,0],['Credit',2700,2700,0],['Partial payment',1700,1700,1000]],
[('Stripe: accounts payable and accounts receivable fundamentals','https://stripe.com/resources/more/accounts-payable-and-accounts-receivable-101-a-guide-for-businesses'),('Xero US: accounts receivable definition','https://www.xero.com/us/glossary/accounts-receivable/')],
'Customer invoice folder and supplier bill folder on opposite sides of an oak desk with a payment calendar between them.',[('Are accounts receivable revenue?','A credit sale can create revenue and AR at recognition, but AR is the outstanding asset balance. Collecting that balance is not another sale.'),('Is paying accounts payable always a new expense?','No. Payment settles the liability. The related asset or expense was recognized according to the original transaction and applicable accounting method.')])

add('cost-performance-index','Cost Performance Index: Earned Value, Actual Cost and Forecast Limits','Cost Performance Index: CPI Formula & Example','Calculate project CPI from earned value and actual cost. Check weighted totals, distinguish CPI from margin, and compare remaining-work forecasts with a printable worksheet.',
'Cost Performance Index, or CPI, equals earned value divided by actual cost for the same project scope and status date. It measures the budgeted value of completed work per dollar of actual cost; it does not measure sales revenue or profit margin.',[
('inputs','Define planned value, earned value and actual cost','<p>Planned value is the approved budget for work scheduled by the status date. Earned value is the approved budget for work actually completed by that date, using a defensible completion method. Actual cost records what that completed work has cost on a consistent accounting basis. Match scope, cut-off and currency before dividing.</p><p><strong>CPI = EV ÷ AC.</strong> Below 1 means the measured work has consumed more actual cost than its budgeted value; above 1 means the opposite. A zero actual-cost denominator needs investigation, not a fabricated finite index. Missing supplier accruals can make CPI look artificially favorable.</p>'),
('case','Calculate cost and schedule performance separately',table('Original fictional project status date',['Measure','Amount / result','Meaning'],[['Budget at completion (BAC)','$100,000','Approved project budget'],['Planned value (PV)','$60,000','Budgeted work scheduled so far'],['Earned value (EV)','$50,000','Budgeted completed work'],['Actual cost (AC)','$62,500','Cost recognized to the status date'],['CPI','0.80','$50,000 ÷ $62,500'],['Cost variance','−$12,500','EV − AC'],['Schedule performance index','0.8333','EV ÷ PV']])+'<p>The project has earned $0.80 of budgeted work for each actual dollar. CPI does not mean a 20% profit loss, and the schedule index does not directly convert into days late. In this example, cost performance and scheduled completion both require investigation, but they describe different dimensions.</p>'),
('forecast','Choose an estimate-at-completion assumption explicitly','<p>If all remaining work can be delivered at its original remaining budget, EAC is AC + (BAC − EV): $62,500 + $50,000 = <strong>$112,500</strong>. If the same cost efficiency is assumed to continue across the total project, EAC is BAC ÷ CPI: $100,000 ÷ 0.80 = <strong>$125,000</strong>. The $12,500 gap is an assumption difference, not an arithmetic error.</p><p>A bottom-up remaining estimate of $58,000 would instead produce EAC of $120,500. Document supplier commitments, remaining quantities, rework and resource rates behind that estimate. Do not select the most reassuring formula without checking what is causing the variance. EAC is a forecast, not a confirmed final invoice.</p>'),
('aggregation','Aggregate dollars before calculating portfolio CPI','<p>Suppose work package A has EV $30,000 and AC $25,000, so CPI is 1.2. Package B has EV $20,000 and AC $37,500, so CPI is approximately 0.5333. The simple average of the two indices is 0.8667, but project CPI is ($30,000 + $20,000) ÷ ($25,000 + $37,500) = <strong>0.80</strong>. Weighting follows the underlying totals.</p><p>Verify completion evidence rather than treating dollars spent as percentage complete. An expensive early purchase can increase actual cost while little eligible work is earned; a milestone-based rule can delay earned value. State those rules and apply them consistently.</p>'),
('action','Turn the ratio into a corrective project decision','<ol><li>Confirm baseline, completion evidence and status-date cut-off.</li><li>Investigate quantity, rate, productivity, scope and rework causes.</li><li>Re-estimate the remaining work from supported inputs.</li><li>Choose and fund the response; log approved scope changes.</li><li>Review the next status date without erasing the original baseline history.</li></ol><p>Use <a href="/blogs/job-order-costing/">job-order costing</a> for recorded job cost and <a href="/blogs/flexible-budget-variance-analysis/">budget variance analysis</a> for driver-specific performance. CPI is a project earned-value measure, separate from a business <a href="/calculators/operating-profit-margin-calculator/">operating margin</a>.</p>')],
['Measure','Value','Calculation'],[['BAC',100000,'Approved baseline'],['PV',60000,'Scheduled work'],['EV',50000,'Completed work'],['AC',62500,'Recognized actual cost'],['CPI',0.8,'EV / AC'],['EAC remaining at budget',112500,'AC + BAC - EV'],['EAC same efficiency',125000,'BAC / CPI'],['Bottom-up EAC',120500,'AC + 58000']],
[('PMI: earned-value data, CPI and executive action','https://www.pmi.org/learning/library/evm-data-analysis-executive-action-8520')],
'Project manager comparing approved completed milestones with an actual-cost ledger beside workshop plans.',[('Can CPI be used as a profit margin?','No. Earned value is budgeted completed work, not customer revenue. A CPI of 0.8 is not an 80% margin.'),('Does EAC equal BAC divided by CPI in every situation?','No. That formula assumes the measured cost efficiency continues. A remaining-at-budget or bottom-up estimate uses different assumptions.')])

add('profitability-index','Profitability Index: Discounted Cash Flows and Project Selection','Profitability Index: Formula, NPV & Worked Example','Calculate profitability index from discounted net cash flows. Reconcile it to NPV, compare project scale and avoid ranking indivisible investments by a ratio alone.',
'Profitability index compares the present value of a project’s future net cash flows with its positive initial investment. Under the stated conventional setup, PI above 1 corresponds to positive NPV, but the ratio alone does not select the best combination of projects.',[
('formula','State the cash-flow convention before calculating PI','<p><strong>PI = present value of future net project cash flows ÷ initial investment.</strong> Here the investment occurs at time zero, future amounts are net incremental project cash flows, and discounting uses end-of-year timing. <strong>NPV = present value of future net cash flows − initial investment.</strong> With these conventions and a positive initial outlay, PI = 1 + NPV ÷ initial investment.</p><p>Some sources use a different numerator or treat later investment outlays separately. Do not compare such ratios without reconciling the definitions. A zero initial investment makes this version undefined. Nonconventional cash flows and multiple later capital commitments need an explicitly rebuilt model.</p>'),
('case','Discount the same project year by year',table('Original fictional project; 10% illustrative discount rate',['Time','Net project cash flow','Discount calculation','Present value'],[['0','−$20,000','Initial investment','−$20,000.00'],['Year 1','$9,000','9000 ÷ 1.10','$8,181.82'],['Year 2','$9,000','9000 ÷ 1.10²','$7,438.02'],['Year 3','$9,000','9000 ÷ 1.10³','$6,761.83'],['Future PV total','$27,000 nominal','Sum of unrounded PV','$22,381.67']])+'<p>PI is $22,381.6679 ÷ $20,000 = <strong>1.1191</strong>. NPV is <strong>$2,381.67</strong>. Retain unrounded discount factors until the final display. The 10% rate is an illustrative input, not a recommended return, borrowing quote or risk-adjusted rate for your business.</p>'),
('meaning','A ratio above one is not an annual return','<p>A PI of 1.1191 means about $1.1191 of discounted future net cash flows for each $1 initially invested in this defined case. It is not an 11.91% annual ROI. Project timing, risk, taxes, replacement needs and a suitable discount rate affect the interpretation. Accounting profit and EBITDA are not substitutes for incremental project cash flow.</p><p>At the same 10% discount rate, reducing each future annual cash flow to $8,000 gives future PV of about $19,894.82, PI of 0.9947 and NPV of −$105.18. A modest assumption change crosses the acceptability threshold, so retain a sensitivity table rather than only the base-case label.</p>'),
('scale','Use NPV and constraints when comparing alternatives','<p>Consider project A requiring $10,000 with future PV $13,000: PI is 1.30 and NPV $3,000. Project B requires $30,000 with future PV $36,000: PI is 1.20 and NPV $6,000. If the projects are mutually exclusive and risk, timing and other constraints are comparable, choosing the higher ratio alone would miss B’s larger dollar NPV.</p><p>Under a fixed budget with indivisible projects, evaluate feasible combinations. Dividing a project into fractions is not automatically possible. Include dependencies, available funding, staff capacity, required assets and strategic obligations. A ratio ranking can assist analysis; it is not a universal capital-allocation rule.</p>'),
('inputs','Build a defensible project cash schedule','<ol><li>Specify the decision and the alternative being compared.</li><li>List incremental cash inflows, operating outflows, working-capital changes, later investment and terminal recoveries.</li><li>Use consistent timing, currency, nominal/real treatment and tax assumptions.</li><li>Document the chosen discount rate and review sensitivities.</li><li>Reconcile PI to NPV and confirm feasibility before approval.</li></ol><p>Use the <a href="/blogs/present-value-vs-future-value/">present-value guide</a> for discounting, the <a href="/calculators/business-roi-calculator/">business investment calculator</a> for its stated return/payback measures, and the <a href="/calculators/cash-flow-forecast-template/">cash forecast</a> to check funding dates. A discounted value result does not ensure cash is available to buy the asset.</p>')],
['Time / result','Net cash flow / value','Note'],[['Initial investment',-20000,'Time zero'],['Year 1',9000,'End of year'],['Year 2',9000,'End of year'],['Year 3',9000,'End of year'],['Discount rate',0.1,'Illustrative'],['PV of future flows','22381.667918858','Keep unrounded values'],['PI','1.119083395943','Future PV / 20000'],['NPV','2381.667918858','Future PV - 20000']],
[('CFI: profitability-index formula and interpretation','https://corporatefinanceinstitute.com/resources/accounting/profitability-index/'),('Wall Street Prep: PI calculation and comparison limits','https://www.wallstreetprep.com/knowledge/profitability-index/')],
'Business owner comparing an equipment investment with future dated cash-flow cards and a capital-project folder.',[('Is PI minus one an annual return?','No. It expresses discounted value relative to initial outlay under the selected horizon and rate, not a compound annual return.'),('Should I always choose the highest PI?','No. Mutually exclusive projects, different scale, indivisibility and funding constraints can change the best feasible choice. Reconcile NPV and the actual decision constraints.')])

cash_addition='<h2 id="cash-close-cutoff-control">Check invoice cut-off before explaining the cash movement</h2><p>Keep three dates for a material credit transaction: delivery/recognition, invoice due date and bank settlement. A receipt against an opening receivable increases cash while reducing that asset; it is not another sale. A supplier payment settles a payable rather than automatically creating a second expense. Reconcile the subsidiary invoice ledgers to the balance-sheet control accounts before using their movements in the operating-cash bridge.</p><div class="article-table-scroll"><table><caption>Illustrative cut-off checks; these do not change the statement example above</caption><thead><tr><th scope="col">Record</th><th scope="col">Question to resolve</th><th scope="col">Evidence</th></tr></thead><tbody><tr><th scope="row">Customer credit</th><td>Was the return recognized in the correct period?</td><td>Accepted credit and original invoice</td></tr><tr><th scope="row">Unapplied receipt</th><td>Is cash posted without clearing the right receivable?</td><td>Bank receipt and customer remittance</td></tr><tr><th scope="row">Supplier bill</th><td>Was an unpaid obligation omitted from the closing ledger?</td><td>Accepted delivery and supplier invoice</td></tr></tbody></table></div><p>Keep this close control separate from the <a href="/calculators/cash-flow-forecast-template/">forecast of future receipts and payments</a>. The historical reconciliation must agree before its balances become forecast inputs.</p>'
review='\nexport function applyTwelveDayExistingReview(post) {\n if(post.slug!=="cash-flow-statement" || post.html.includes("cash-close-cutoff-control")) return post;\n if(post.modified>"2026-10-25") return post;\n return {...post, modified:twelveDayRelease.date, html:post.html+'+json.dumps(cash_addition)+'};\n}\n'
seo_overrides=[
('Customer Profitability: Formula & Example','Measure customer profit with a reconciled cost-to-serve example. Separate avoidable costs, shared overhead and cash timing before changing an account.'),
('ROAS vs ROI: Costs & Worked Example','Compare ROAS and ROI using one campaign ledger. Include refunds, product costs and creative fees, and state the investment denominator before comparing returns.'),
('Sales Forecast Formula & Business Template','Build a sales forecast from units, price and customer evidence. Check capacity, separate bookings from cash and compare scenarios with an editable worksheet.'),
('Cost Volume Profit Analysis: Scenarios','Test price, costs, volume, sales mix and capacity with CVP analysis. Reconcile break-even and target profit before accepting a higher fixed-cost commitment.'),
('Cost per Hire vs Employee Cost: Example','Calculate recruiting cost per completed hire, then build a first-year employment budget. Include internal time consistently without double-counting onboarding.'),
('Financial Contingency Plan & Template','Build a financial contingency plan with dated cash scenarios, triggers, owners and verified funding. Test an original cash-gap example and response worksheet.'),
('Receivables vs Payables: Entries & Cash','Compare receivables and payables with matched entries. Reconcile an invoice, credit and partial payment without confusing revenue, expense and cash.'),
('Cost Performance Index: CPI Formula','Calculate CPI from earned value and actual cost. Check weighted totals, separate project cost performance from margin and compare remaining-work forecasts.'),
('Profitability Index: Formula & NPV Example','Calculate profitability index from discounted cash flows. Reconcile NPV, compare project scale and avoid ranking indivisible investments by a ratio alone.')]
extra_faq=[
[('Which cost driver should I use?','Choose a documented measure that explains the activity, such as support hours or shipments. Reconcile the allocated pool and show any unassigned cost.'),('Can profit be positive while collections are late?','Yes. Accrual revenue and customer contribution do not establish available cash. Track invoice due dates and receipts separately.')],
[('Should refunds change the revenue input?','Use a consistently defined net revenue measure and a matched return window. Do not subtract a refund again if it is already netted in the input.'),('Does reported ROAS prove advertising caused the sales?','No. Attribution assigns credit under a model. Incrementality requires evidence about sales that would not have happened without the campaign.')],
[('How should I handle an upside above capacity?','Label it a demand scenario and calculate the additional worker-hours or other constrained resources before treating it as deliverable revenue.'),('What error denominator does the example use?','It divides the revenue shortfall by forecast revenue. State the denominator because using actual revenue produces another percentage.')],
[('What if contribution per unit is negative?','With the same price and variable rate, additional units deepen the contribution shortfall. Resolve the economics before dividing fixed costs by contribution.'),('Why does the product mix matter?','Each offer can contribute a different amount. The weighted contribution is valid only for the stated mix and cost range.')],
[('How should internal interview time be valued?','Use a documented, consistently applied hourly cost or internal rate. Keep it separate from cash-only recruiting spend and avoid adding the same staff cost twice.'),('Is lower cost per hire always better?','No. Role mix, timing, sample size, retention and hiring outcomes affect the comparison. A low ratio can conceal repeated replacement hiring.')],
[('Does rescheduling a supplier bill remove the cost?','No. It moves the cash obligation to another date, subject to agreement. Include that later payment when checking the next forecast periods.'),('How often should the plan be reviewed?','Choose a cadence that matches the payment risk, and review immediately when a material assumption fails. The example uses more frequent escalation under stress.')],
[('Does a partial payment change the original invoice revenue?','Not by itself. In the stated accrual example it reduces the open receivable/payable and moves cash. A valid credit or correction is a separate event.'),('Should balances with the same counterparty be netted?','Do not net them casually. Check the applicable accounting offsetting rules and agreements, and retain the underlying records.')],
[('Can I average work-package CPI values?','Calculate total earned value divided by total actual cost. A simple average of ratios can misstate the project because packages have different cost weights.'),('What happens when actual cost is zero?','The division is undefined. Investigate missing costs, timing or completion rules rather than presenting a finite CPI value.')],
[('What cash flows belong in PI?','Use the explicitly defined incremental project cash flows, timing and rate. Include later investment and terminal effects consistently with the chosen convention.'),('Why keep unrounded discount factors?','Rounding each year early can change the reported total. Sum unrounded present values, then round the displayed PI and NPV.')]
]
for i,p in enumerate(posts):
 p['seoTitle'],p['metaDescription']=seo_overrides[i];p['description']=p['metaDescription'];p['faq'] += [dict(q=q,a=a)for q,a in extra_faq[i]]
 assert len(p['seoTitle']+' | MyBreakeven')<=60
 assert 120<=len(p['metaDescription'])<=160,(p['slug'],len(p['metaDescription']))
diagram_dir=ROOT/'public/images/diagrams';diagram_dir.mkdir(exist_ok=True)
def pt(q,value):return f'{90+q*2.5:.2f},{410-value*.008:.2f}'
svg='<svg xmlns="http://www.w3.org/2000/svg" width="960" height="520" viewBox="0 0 960 520" role="img" aria-labelledby="t d"><title id="t">CVP revenue and total cost at different sold volumes</title><desc id="d">Revenue at 120 dollars per unit crosses total costs of 9600 dollars plus 72 dollars per unit at 200 units and 24000 dollars. Capacity beyond 260 units requires a separate cost model.</desc><rect width="960" height="520" fill="#f4faf9"/><g font-family="Arial,sans-serif" fill="#163443"><text x="55" y="42" font-size="25" font-weight="bold">CVP: the original relevant-range model</text><text x="55" y="72" font-size="17">Fictional USD monthly example - before adding capacity costs</text>'
for value in [0,10000,20000,30000,40000]:
 y=410-value*.008;svg+=f'<path d="M90 {y}H860" stroke="#ccdedd"/><text x="10" y="{y+6}" font-size="16">${value:,}</text>'
for q in [0,100,200,300]:svg+=f'<text x="{90+q*2.5-9}" y="439" font-size="17">{q}</text>'
svg+='<polyline points="'+' '.join(pt(q,q*120)for q in [0,100,200,300])+'" fill="none" stroke="#087e83" stroke-width="5"/><polyline points="'+' '.join(pt(q,9600+q*72)for q in [0,100,200,300])+'" fill="none" stroke="#c25438" stroke-width="5"/><circle cx="590" cy="218" r="7" fill="#163443"/><text x="390" y="193" font-size="20" font-weight="bold">Break-even: 200 units / $24,000</text><path d="M650 477H695" stroke="#087e83" stroke-width="5"/><text x="705" y="483" font-size="17">Revenue</text><path d="M90 477H135" stroke="#c25438" stroke-width="5"/><text x="145" y="483" font-size="17">Total cost</text><text x="410" y="469" font-size="17">Sold units</text></g></svg>'
(diagram_dir/'cvp-relevant-range-20261103.svg').write_text(svg)
cvp=next(p for p in posts if p['slug']=='cost-volume-profit-analysis')
cvp['html']=cvp['html'].replace('<h2 id="range">','<figure><img src="/images/diagrams/cvp-relevant-range-20261103.svg" width="960" height="520" style="max-width:100%;height:auto" loading="lazy" alt="Revenue and total cost cross at 200 units and $24,000 under the stated original CVP assumptions."/><figcaption>Exact chart of the original fixed-cost range. Rebuild the cost line when capacity adds another commitment.</figcaption></figure><h2 id="range">')
target=ROOT/'src/content/blogs/twelveDayDay1.js';target.write_text("import {twelveDayRelease} from '../../twelveDayRelease.js';\nconst twelveDayDay1Drafts = "+json.dumps(posts,ensure_ascii=False,indent=2)+';\nexport const twelveDayDay1Posts = twelveDayDay1Drafts.map(p=>({...p,cluster:"concepts",editorialStatus:twelveDayRelease.published?"published":"draft",published:twelveDayRelease.date,modified:twelveDayRelease.date}));\n'+review)
report=[{'slug':p['slug'],'words':len(re.sub('<[^>]+>',' ',p['html']).split()),'sections':len(p['sectionLinks']),'status':p['editorialStatus']}for p in posts]
(ROOT/'docs/content/2026-11-03-day1-draft-metrics.json').write_text(json.dumps(report,indent=2))
print(json.dumps(report,indent=2))
